/* ========== 自定义勾选框 框架来源@千尾老师 ========== */
/* 1. 基础框架 */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  position: relative;
  width: 22px; /* 图片宽度 */
  height: 22px; /* 图片高度 */

  /* 用背景图代替边框 */
  border: none !important;
  outline: none !important;
  background-color: transparent !important;

  /* 背景图通用设置 */
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;

  transition: all 0.2s ease-in-out;
  box-shadow: none !important;
  margin: 0 3px 0 0;
  transform: translateY(4px); /* Y轴微调 */
  cursor: pointer;
}

/* 2. 未选中时：加载“关闭”状态的图片 */
input[type="checkbox"]:not(:checked) {
  background-image: url('https://i.postimg.cc/BQ4HpKDK/wu-biao-ti178-20260413172239.png ') !important;
  opacity: 0.8; /* 未选中时轻微变暗 */
}

/* 3. 选中时：加载“开启”状态的图片 */
input[type="checkbox"]:checked {
  background-image: url('https://i.postimg.cc/Nfk7v4YC/wu-biao-ti178-20260413172206.png ') !important;
  opacity: 1;
  transform: translateY(4px) scale(1.1); /* 选中轻微放大 */
}

/* 4. 去除自带伪元素冲突 */
input[type="checkbox"]::after,
input[type="checkbox"]::before {
    content: none !important;
}

